/* ── Mobile disclosure menu (gh-756, re-measured for gh-881) ────────────
   Below 1080px the links collapse behind a ☰ toggle (JS only handles Esc /
   backdrop / focus / aria; open-close itself is CSS via [data-open]).
   The breakpoint is MEASURED, not guessed: the 11-link row was 843px wide
   + 48px padding for the 10-link set (fit from ~892px, collapse at the
   site's 960 breakpoint); the gh-881 header badge adds ~135px, so the row
   now fits only from ~1050px — at 961-1049 it wrapped nav-ext to a second
   row (E2). 1080 is the round breakpoint with headroom.
   The toggle exists only under html.js AND the 1080px breakpoint; the
   `hidden` attribute keeps it gone with no CSS or no JS (E6: the no-JS
   fallback is the wrapped-links layout at ≤640px below, never a dead
   button). */
.nav-menu { display: contents; }
.nav-toggle {
  display: none; /* CSS-gated everywhere; the media query below re-shows it */
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  background: rgba(148, 163, 184, 0.08);
  border: 1px solid var(--border-bright);
  border-radius: 9px;
  cursor: pointer;
}
.nav-toggle:hover { border-color: var(--accent); }
.nav-toggle .icon-close { display: none; }
.nav-toggle[aria-expanded="true"] .icon-open { display: none; }
.nav-toggle[aria-expanded="true"] .icon-close { display: inline; }

@media (max-width: 1080px) {
  html.js .nav-inner { flex-wrap: nowrap; gap: 14px; padding: 12px 18px; }
