     matchMedia('(min-width: 1081px)') rotate auto-close,
     scripts/site_mobile_check.mjs MENU_MAX_WIDTH. */
  html.js .nav-toggle { display: inline-flex; margin-left: auto; }
  /* Conscious brand-sub decision (audit #3): it hides in the collapsed
     header, and now the collapse starts at 1080, not 640 (gh-881
     re-measure). */
  html.js .brand-sub { display: none; }
