// Fit probe v2: natural row width = sum(child offsetWidth) + inner gaps.
import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
const require = createRequire(import.meta.url);
const { chromium } = require('playwright');

const root = process.argv[2];
const port = 8125;
const server = spawn('python3', ['-m', 'http.server', String(port)], { cwd: root, stdio: 'ignore' });
await new Promise(r => setTimeout(r, 800));
try {
  const browser = await chromium.launch();
  for (const w of [1081, 1090, 1106, 1120, 1168, 1280, 1440, 1920]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: 900 } });
    const page = await ctx.newPage();
    await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: 'load' });
    await page.waitForTimeout(200);
    const m = await page.evaluate(() => {
      const inner = document.querySelector('.nav-inner');
      const nav = document.querySelector('.nav').getBoundingClientRect();
      const cs = getComputedStyle(inner);
      const colGap = parseFloat(cs.columnGap);
      const kids = [...inner.children].filter(el => {
        const s = getComputedStyle(el);
        return s.display !== 'none';
      });
      // natural width: everything unshrunk, links forced nowrap
      kids.forEach(el => { el.style.flexShrink = '0'; });
      const links = document.querySelector('.nav-links');
      const aList = [...links.children];
      aList.forEach(a => { a.style.whiteSpace = 'nowrap'; });
      const nat = kids.reduce((s, el) => s + el.getBoundingClientRect().width, 0)
        + colGap * (kids.length - 1);
      const avail = inner.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
      kids.forEach(el => { el.style.flexShrink = ''; });
      aList.forEach(a => { a.style.whiteSpace = ''; });
      const linkHs = aList.map(a => Math.round(a.getBoundingClientRect().height));
      return { nat: Math.round(nat), avail, navH: Math.round(nav.height), maxLinkH: Math.max(...linkHs) };
    });
    const verdict = m.navH <= 70 && m.nat <= m.avail ? 'FITS' : `WRAPS/OVER by ${m.nat - m.avail}`;
    console.log(`@${w}: natural=${m.nat} avail=${m.avail} navH=${m.navH} maxLinkH=${m.maxLinkH} → ${verdict}`);
    await ctx.close();
  }
  await browser.close();
} finally { server.kill(); }

