import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
const require = createRequire(import.meta.url);
const { chromium } = require('playwright');
const root = process.argv[2];
const port = 8126;
const server = spawn('python3', ['-m', 'http.server', String(port)], { cwd: root, stdio: 'ignore' });
await new Promise(r => setTimeout(r, 800));
try {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: 'load' });
  await page.waitForTimeout(200);
  const m = await page.evaluate(() => {
    const inner = document.querySelector('.nav-inner');
    const cs = getComputedStyle(inner);
    const boxes = ['.brand', '.store-badge', '.nav-links', '.nav-ext'].map(s => {
      const el = document.querySelector(s);
      el.style.flexShrink = '0';
      const r = el.getBoundingClientRect();
      return { s, w: Math.round(r.width) };
    });
    document.querySelectorAll('.nav-links a').forEach(a => a.style.whiteSpace = 'nowrap');
    const gap = parseFloat(cs.columnGap);
    const nat = boxes.reduce((s, b) => s + b.w, 0) + gap * 3;
    const avail = inner.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
    boxes.forEach(b => { document.querySelector(b.s).style.flexShrink = ''; });
    return { boxes, gap, nat: Math.round(nat), avail };
  });
  console.log(JSON.stringify(m));
  await browser.close();
} finally { server.kill(); }
EOF
