import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
const require = createRequire(import.meta.url);
const { chromium } = require('playwright');
const root = process.argv[2];
const port = 8128;
const server = spawn('python3', ['-m', 'http.server', String(port)], { cwd: root, stdio: 'ignore' });
await new Promise(r => setTimeout(r, 800));
try {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: 'load' });
  await page.waitForTimeout(200);
  const r = await page.evaluate(() => {
    const inner = document.querySelector('.nav-inner');
    const links = document.querySelector('.nav-links');
    const set = (el, g) => el.style.gap = g;
    set(inner, '28px'); set(links, '20px');
    inner.style.width = 'max-content';
    const oldW = Math.round(inner.getBoundingClientRect().width) - 48;
    inner.style.width = '';
    set(inner, '20px'); set(links, '14px');
    inner.style.width = 'max-content';
    const newW = Math.round(inner.getBoundingClientRect().width) - 48;
    inner.style.width = '';
    // also: 9-link row on main with old gaps (drop the Bench link)
    const bench = [...links.querySelectorAll('a')].find(a => a.textContent.trim() === 'Bench');
    bench.style.display = 'none';
    set(inner, '28px'); set(links, '20px');
    inner.style.width = 'max-content';
    const mainW = Math.round(inner.getBoundingClientRect().width) - 48;
    inner.style.width = '';
    bench.style.display = '';
    return { oldW, newW, mainW };
  });
  console.log(JSON.stringify(r));
  await browser.close();
} finally { server.kill(); }
EOF
